import{_ as a,o,a as r,b as t}from"./app.DKoEZOcr.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"附录","link":"/guide/programming_guide/appendix/show_kernel_debug_data_tool"},{"text":"常用操作","link":"/guide/programming_guide/appendix/common_operations/develop_dynamic_input_operator"},{"text":"如何使用workspace","link":"/guide/programming_guide/appendix/common_operations/how_to_use_workspace"}]},"headers":[],"relativePath":"guide/programming_guide/appendix/common_operations/how_to_use_workspace.md","filePath":"guide/programming_guide/appendix/common_operations/how_to_use_workspace.md","lastUpdated":1787646178000}'),i={name:"guide/programming_guide/appendix/common_operations/how_to_use_workspace.md"};function p(s,e,c,n,l,_){return o(),r("div",null,[...e[0]||(e[0]=[t(`<div><article class="markdown-body"><h1>如何使用workspace<span id="ZH-CN_TOPIC_0000001566726840"></span></h1><p>workspace是设备侧Global Memory上的一块内存。workspace内存分为两部分：系统workspace和用户workspace。</p><ul><li><p>系统workspace：Ascend C API需要预留的workspace内存</p><p>API在计算过程需要一些workspace内存作为缓存，因此算子需要为API预留workspace内存，预留内存大小通过<a href="../../../../api/Utils-API/platform_info/PlatformAscendC/GetLibApiWorkSpaceSize.html">GetLibApiWorkSpaceSize</a>接口获取。</p></li><li><p>用户workspace：算子实现使用到的workspace内存</p><p>算子内部需要通过额外的device内存进行数据交换或者缓存的时候才需要分配，根据实际情况自行分配。使用场景如下：</p><ul><li>需要使用Unified Buffer（UB）和L1 Buffer上的空间且空间不够用时，可以将数据暂存至workspace上。</li><li>调用<a href="../../../../api/SIMD-API/basic_api/sync_control/inter_core_sync/SyncAll.html">SyncAll</a>等API接口时，需要workspace作为入参。</li><li>其他需要使用Global Memory上内存空间的场景。</li></ul></li></ul><p>不同开发方式下，具体的使用方法如下：</p><ul><li><p>工程化算子开发方式</p><p>在tiling函数中先通过GetWorkspaceSizes接口获取workspace大小的存放位置，再设置workspace的大小，框架侧会为其申请对应大小的设备侧Global Memory，在对应的算子kernel侧实现时可以使用这块workspace内存。在使用<a href="../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel.html">Matmul核函数（Kernel）侧接口</a>等需要系统workspace的高阶API时，设置的workspace空间大小为系统workspace和用户workspace之和。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 用户自定义的tiling函数
static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    AddApiTiling tiling;
    ...
    size_t usrSize = 256; // 设置用户需要使用的workspace大小为256字节。
    // 如需要使用系统workspace需要调用GetLibApiWorkSpaceSize获取系统workspace的大小。
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
    uint32_t sysWorkspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();
    if (sysWorkspaceSize == std::numeric_limits&lt;uint32_t&gt;::max()) {
        return ge::GRAPH_FAILED;
    }
    size_t *currentWorkspace = context-&gt;GetWorkspaceSizes(1); // 通过框架获取workspace的指针，GetWorkspaceSizes入参为所需workspace的块数。当前限制使用一块。
    currentWorkspace[0] = usrSize + sysWorkspaceSize; // 设置总的workspace的数值大小，总的workspace空间由框架来申请并管理。
    ...
}
</code></pre></div><p>在device侧kernel入口处的workspace为用户的workspace指针：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 用户写的核函数（Kernel），核函数（Kernel）必须包括GM_ADDR workspace入参，位置需要放在tiling之前
extern &quot;C&quot; __global__ __aicore__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR workspace, GM_ADDR tiling)
{
    ...
    
}
</code></pre></div></li><li><p>核函数（Kernel）直调算子开发场景</p><p>需要使用workspace空间时，建议开启编译选项<a href="../kernel_direct_call_from_sample.html#li1103101565014">HAVE_WORKSPACE</a>。host侧开发者仍需要自行申请workspace的空间，并传入。在使用Matmul核函数（Kernel）侧接口等需要系统workspace的高阶API时，设置的workspace空间大小为系统workspace和用户workspace之和。系统workspace大小可以通过PlatformAscendCManager的GetLibApiWorkSpaceSize接口获取。开启<a href="../kernel_direct_call_from_sample.html#li1103101565014">HAVE_WORKSPACE</a>后，开发者在kernel侧入参处获取的workspace为偏移了系统workspace后的用户workspace。</p></li></ul></article></div>`,1)])])}const m=a(i,[["render",p]]);export{k as __pageData,m as default};
